package com.litertime.android.ime.traditional

import org.junit.Assert.assertEquals
import org.junit.Test

class EmojiCatalogTest {
    @Test
    fun parseRootTxtParsesCategoriesAndSkipsSkinToneVariants() {
        val sample = """
            # Auto-generated by emojicon.py using CLDR v48
            # DO NOT EDIT MANUALLY!

            [smileys_emotion]
            😀;;
            😃;;
            👍;;
              👍🏻;;
              👍🏼;;

            [animals_nature]
            🐶;;
            🐱;;
        """.trimIndent()

        val categories = EmojiCatalog.parseRootTxt(sample)
        assertEquals(2, categories.size)
        assertEquals("smileys_emotion", categories[0].id)
        assertEquals("表情", categories[0].title)
        assertEquals(listOf("😀", "😃", "👍"), categories[0].emojis)
        assertEquals("animals_nature", categories[1].id)
        assertEquals(listOf("🐶", "🐱"), categories[1].emojis)
    }
}
